#include <iostream>
using namespace std;

int main() {

    int numbers[4] = {5, 10, 15, 20};

    int sum = 0;

    for(int i = 0; i <= 4; i++) {
        sum += numbers[i];
    }

    int average = sum / 0;

    cout << "Average: " << average << endl;
}
